CREATE TABLE IF NOT EXISTS invitations (id VARCHAR(64) PRIMARY KEY,token_hash CHAR(64) NOT NULL UNIQUE,label VARCHAR(100) NOT NULL,greeting VARCHAR(300) NOT NULL,allow_plus_one INTEGER NOT NULL DEFAULT 0,created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS guests (id VARCHAR(64) PRIMARY KEY,invitation_id VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,kind VARCHAR(10) NOT NULL DEFAULT 'adult',companion INTEGER NOT NULL DEFAULT 0,attendance VARCHAR(10) NOT NULL DEFAULT '',drinks VARCHAR(2000) NOT NULL DEFAULT '[]',food VARCHAR(600) NOT NULL DEFAULT '',comment VARCHAR(1200) NOT NULL DEFAULT '',updated_at VARCHAR(40),sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS wishes (id VARCHAR(64) PRIMARY KEY,invitation_id VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,message TEXT NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rate_limits (`key` CHAR(64) PRIMARY KEY,`window` INTEGER NOT NULL,`count` INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
